Below is a simple **Qt 5 + C++** example that opens a GUI, lets the user choose a folder, and then converts all Excel files in that folder into **CSV** files in a **new subfolder**.

### Important note
This version uses **Microsoft Excel via ActiveQt (`QAxObject`)**, so it is:

- **Windows-only**
- Requires **Microsoft Excel installed**

Also, since CSV is single-sheet only, this converts each workbook using Excel’s **first/active sheet**.

---

## `main.cpp`

```cpp
#include <QApplication>
#include <QWidget>
#include <QPushButton>
#include <QVBoxLayout>
#include <QFileDialog>
#include <QMessageBox>
#include <QDir>
#include <QDirIterator>
#include <QFileInfo>
#include <QLabel>

#include <ActiveQt/QAxObject>

class ExcelConverter : public QWidget
{
public:
    ExcelConverter(QWidget *parent = nullptr) : QWidget(parent)
    {
        setWindowTitle("Excel to CSV Converter");
        resize(400, 150);

        auto *layout = new QVBoxLayout(this);

        label = new QLabel("Choose a folder containing Excel files.", this);
        layout->addWidget(label);

        convertButton = new QPushButton("Select Folder and Convert", this);
        layout->addWidget(convertButton);

        connect(convertButton, &QPushButton::clicked, this, &ExcelConverter::chooseFolderAndConvert);
    }

private:
    QLabel *label;
    QPushButton *convertButton;

    void chooseFolderAndConvert()
    {
        QString folder = QFileDialog::getExistingDirectory(
            this,
            "Select Folder Containing Excel Files"
        );

        if (folder.isEmpty())
            return;

        QString outputFolder = folder + "/csv_output";
        QDir dir;
        if (!dir.exists(outputFolder))
            dir.mkpath(outputFolder);

        int convertedCount = 0;

        // Excel file extensions to process
        QStringList filters = {"*.xls", "*.xlsx", "*.xlsm", "*.xlsb"};

        QDirIterator it(folder, filters, QDir::Files);
        while (it.hasNext())
        {
            QString excelFilePath = it.next();
            QFileInfo info(excelFilePath);

            QString csvFilePath = outputFolder + "/" + info.completeBaseName() + ".csv";

            if (convertExcelToCsv(excelFilePath, csvFilePath))
                convertedCount++;
        }

        QMessageBox::information(
            this,
            "Done",
            QString("Conversion complete.\nConverted %1 file(s).\nOutput folder:\n%2")
                .arg(convertedCount)
                .arg(outputFolder)
        );
    }

    bool convertExcelToCsv(const QString &excelPath, const QString &csvPath)
    {
        QAxObject excel("Excel.Application");
        if (excel.isNull())
        {
            QMessageBox::critical(this, "Error", "Could not start Microsoft Excel.");
            return false;
        }

        excel.setProperty("Visible", false);
        excel.setProperty("DisplayAlerts", false);

        QAxObject *workbooks = excel.querySubObject("Workbooks");
        if (!workbooks)
        {
            QMessageBox::critical(this, "Error", "Could not access Excel workbooks.");
            excel.dynamicCall("Quit()");
            return false;
        }

        QAxObject *workbook = workbooks->querySubObject("Open(const QString&)", excelPath);
        if (!workbook)
        {
            QMessageBox::warning(this, "Warning", "Failed to open: " + excelPath);
            excel.dynamicCall("Quit()");
            return false;
        }

        // Make sure first sheet is active
        QAxObject *sheets = workbook->querySubObject("Worksheets");
        if (sheets)
        {
            QAxObject *sheet = sheets->querySubObject("Item(int)", 1);
            if (sheet)
                sheet->dynamicCall("Activate()");
        }

        // 6 = xlCSV
        // SaveAs(filename, fileFormat)
        workbook->dynamicCall("SaveAs(const QString&, int)", csvPath, 6);

        workbook->dynamicCall("Close()");
        excel.dynamicCall("Quit()");

        return true;
    }
};

int main(int argc, char *argv[])
{
    QApplication app(argc, argv);

    ExcelConverter window;
    window.show();

    return app.exec();
}
```

---

## `*.pro` file

If you’re using qmake, add this:

```pro
QT += widgets axcontainer
CONFIG += c++11

SOURCES += main.cpp
```

---

## How it works

1. User clicks the button.
2. A folder selection dialog appears.
3. The program creates a new folder called:
   - `csv_output`
4. It searches for:
   - `*.xls`
   - `*.xlsx`
   - `*.xlsm`
   - `*.xlsb`
5. Each Excel file is opened in Excel and saved as a `.csv` file in the output folder.

---

## Notes / limitations

- This only works on **Windows**
- Requires **Microsoft Excel installed**
- CSV only stores one sheet, so it saves the **first/active worksheet**
- If your workbook has multiple sheets, you may want a different conversion strategy

---

If you want, I can also provide:
1. a version using **QXlsx** instead of Microsoft Excel, or  
2. a version that converts **each worksheet into a separate CSV**.

